241	    @Override
242	    @Transactional
243	    public void saveOwner(Owner owner) throws DataAccessException {
244	        if (owner.isNew()) {
245	            if (owner.getRegistrationDate() == null) {
246	                owner.setRegistrationDate(LocalDate.now());
247	            }
248	            if (isDailyRegistrationLimitReached(owner)) {
249	                throw new OwnerRegistrationLimitException(
250	                    "The maximum number of owners that can be registered today has been reached");
251	            }
252	            if (isCityCapacityReached(owner)) {
253	                throw new OwnerCityCapacityException(
254	                    "The maximum number of owners that can be registered in this city has been reached");
255	            }
256	            owner.setCity(resolveCity(owner));
257	            owner.setMembershipNumber(ownerRepository.findAll().size() + 1);
258	            owner.setMembershipTier(owner.getMembershipNumber() <= MAX_FOUNDING_OWNERS ? "FOUNDING" : "STANDARD");
259	            owner.setCustomerCode(generateCustomerCode(owner));
260	            owner.setNamesakeCount(countNamesakes(owner));
261	            owner.setSharesHousehold(sharesHousehold(owner));
262	            if (isDuplicateTelephone(owner)) {
263	                throw new DuplicateOwnerException(
264	                    "An owner with the same telephone already exists");
265	            }
266	            if (isDuplicateEmail(owner)) {
267	                throw new DuplicateOwnerException(
268	                    "An owner with the same email already exists");
269	            }
270	        }
271	        ownerRepository.save(owner);
272	
273	    }
274	
275	    /**
276	     * Count how many other owners already share this owner's last name at the
277	     * moment of creation (compared case-insensitively). The owner being created
278	     * is not yet persisted and is therefore never included in the count.
279	     */
280	    private int countNamesakes(Owner owner) {
281	        String lastName = owner.getLastName();
282	        if (lastName == null) {
283	            return 0;
284	        }
285	        return (int) ownerRepository.findAll().stream()
286	            .filter(existing -> !existing.getId().equals(owner.getId()))
287	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
288	            .count();
289	    }
290	
291	    /**
292	     * Determine whether a newly created owner shares a household with an
293	     * existing owner, i.e. another owner already has the same address and city
294	     * (both compared case-insensitively) at the moment of creation. The owner
295	     * being created is not yet persisted and is therefore never matched against
296	     * itself.
297	     */
298	    private boolean sharesHousehold(Owner owner) {
299	        String address = owner.getAddress();
300	        String city = owner.getCity();
301	        if (address == null || city == null) {
302	            return false;
303	        }
304	        return ownerRepository.findAll().stream()
305	            .filter(existing -> !existing.getId().equals(owner.getId()))
306	            .anyMatch(existing -> address.equalsIgnoreCase(existing.getAddress())
307	                && city.equalsIgnoreCase(existing.getCity()));
308	    }
309	
310	    /**
311	     * Build a customer code for a newly created owner, formatted as
312	     * {@code <UPPERCASE_CITY>-<NNNN>} where NNNN is one more than the number of
313	     * owners already registered in that city, zero-padded to four digits
314	     * (e.g. {@code LONDON-0007}).
315	     */
316	    private String generateCustomerCode(Owner owner) {
317	        String city = owner.getCity();
318	        long existingInCity = ownerRepository.findAll().stream()
319	            .filter(existing -> !existing.getId().equals(owner.getId()))
320	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
321	            .count();
322	        String prefix = city == null ? "" : city.toUpperCase(Locale.ROOT);
323	        return String.format("%s-%04d", prefix, existingInCity + 1);
324	    }
325	
326	    /**
327	     * Determine the city to store for a newly created owner. If another owner is
328	     * already registered in the same city (compared case-insensitively), reuse
329	     * that owner's exact spelling of the city name so the whole clinic agrees on
330	     * one canonical form. Otherwise the supplied city is title-cased (each
331	     * whitespace-separated word capitalised, e.g. "new york" becomes
332	     * "New York"). A {@code null} city stays {@code null}.
333	     */
334	    private String resolveCity(Owner owner) {
335	        String city = owner.getCity();
336	        if (city == null) {
